def read_ignore_patterns(root: str) -> list[str]:
    pats: list[str] = []
    for name in (".gitignore", ".ignore"):
        p = os.path.join(root, name)
        if os.path.isfile(p):
            try:
                for raw in open(p, encoding="utf-8").read().splitlines():
                    line = raw.strip()
                    if not line or line.startswith("#"):
                        continue
                    pats.append(line)
            except OSError:
                pass
    return pats


def ignored(rel: str, is_dir: bool, patterns: list[str]) -> bool:
    parts = rel.split(os.sep)
    if any(part.startswith(".") and part not in (".", "..") for part in parts):
        return True
    rel_posix = rel.replace(os.sep, "/")
    name = os.path.basename(rel)
    for pat in patterns:
        neg = pat.startswith("!")
        if neg:
            continue
        p = pat.rstrip("/")
        dir_pat = pat.endswith("/")
        if dir_pat and not is_dir and not rel_posix.startswith(p + "/"):
            continue
        if fnmatch.fnmatch(rel_posix, p) or fnmatch.fnmatch(name, p) or rel_posix.startswith(p + "/"):
            return True
    return False


def walk_dir(root: str) -> list[str]:
    result: list[str] = []
    patterns = read_ignore_patterns(root)
    def rec(d: str):
        try:
            entries = list(os.scandir(d))
        except OSError:
            return
        dirs = [e for e in entries if e.is_dir(follow_symlinks=False)]
        files = [e for e in entries if e.is_file(follow_symlinks=False)]
        for de in dirs:
            rel = os.path.relpath(de.path, root)
            if ignored(rel, True, patterns):
                continue
            rec(de.path)
        for fe in files:
            rel = os.path.relpath(fe.path, root)
            if ignored(rel, False, patterns):
                continue
            if Path(fe.name).suffix in FORMAT_EXTS:
                if root == "." or root == "./":
                    result.append(os.path.join(".", rel))
                else:
                    result.append(fe.path)
    rec(root)
    return result


def collect_files(opts: Options, original_args: list[str]) -> tuple[list[str], str | None]:
    # returns files, error_message (without level)
    if opts.recursive:
        files: list[str] = []
        if not original_args:
            files.extend(walk_dir("."))
        else:
            for arg in original_args:
                if os.path.isdir(arg):
                    files.extend(walk_dir(arg.rstrip(os.sep) if arg != os.sep else arg))
                else:
                    path = normalize_filename_for_display(arg)
                    if os.path.isfile(path):
                        files.append(path)
        if not files:
            return [], "No files specified. Provide filenames, or pass --recursive or --stdin."
        return files, None
    if not original_args:
        return [], "No files specified. Provide filenames, or pass --recursive or --stdin."
    files = []
    for arg in original_args:
        if os.path.isdir(arg):
            return [], "A directory was passed without --recursive."
        files.append(normalize_filename_for_display(arg))
    return files, None


def process_file(path: str, opts: Options) -> int:
    logger = Logger(opts, path)
    try:
        data = Path(path).read_bytes()
    except OSError:
        logger.error("Could not open file.")
        return 1
    text = data.decode("utf-8", errors="replace")
    out = format_text(text, opts, path)
    changed = (out != text)
    rc = 0
    if opts.print_:
        sys.stdout.write(out)
    elif opts.check:
        if changed:
            logger.error("Incorrect formatting.")
            rc = 1
    else:
        if changed:
            try:
                Path(path).write_text(out, encoding="utf-8")
            except OSError:
                logger.error("Could not write file.")
                return 1
            if opts.fail_on_change:
                logger.info("Fixed incorrect formatting.")
                rc = 1
    return rc


def main(argv: list[str]) -> int:
    prog = os.path.basename(sys.argv[0]) or "executable"
    try:
        cli = parse_cli(argv, prog)
        # Capture original positional spelling for directory detection; parse_cli
        # normalized display names already.  Reconstruct by a small second pass.
        original_files = []
        stop = False; skip_next = False
        val_opts = {"--wraplen", "--tabsize", "--config", "--completion"}
        short_need = None
        i = 0
        while i < len(argv):
            a = argv[i]
            if skip_next:
                skip_next = False; i += 1; continue
            if stop:
                original_files.append(a); i += 1; continue
            if a == "--": stop = True; i += 1; continue
            if a.startswith("--"):
                name = a.split("=",1)[0]
                if name in val_opts and "=" not in a:
                    skip_next = True
                i += 1; continue
            if a.startswith("-") and a != "-":
                # short cluster with l/t consumes rest or next
                cl = a[1:]
                consumed_next = False
                for pos,ch in enumerate(cl):
                    if ch in "lt":
                        if pos == len(cl)-1:
                            consumed_next = True
                        break
                if consumed_next:
                    skip_next = True
                i += 1; continue
            original_files.append(a); i += 1
        # Early clap-generated outputs do not need config.
        if cli.help:
            sys.stdout.write(help_text(prog))
            return 0
        if cli.version:
            print(f"tex-fmt {VERSION}")
            return 0
        if cli.completion is not None:
            sys.stdout.write(completion_script(cli.completion))
            return 0
        if cli.man:
            sys.stdout.write(man_page())
            return 0
        opts = apply_config(cli)
    except ParseExit as pe:
        return pe.code
    if opts.args:
        print_args(opts)
        return 0
    if opts.stdin:
        if opts.files:
            Logger(opts, "").error("Do not provide file name(s) when using --stdin.")
            return 1
        data = sys.stdin.buffer.read()
        text = data.decode("utf-8", errors="replace")
        out = format_text(text, opts, "<stdin>", stdin_bytes=len(data))
        sys.stdout.write(out)
        return 0
    files, err = collect_files(opts, original_files)
    if err is not None:
        Logger(opts, "").error(err)
        return 1
    rc = 0
    for f in files:
        r = process_file(f, opts)
        if r != 0:
            rc = r
    return rc


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
