#!/usr/bin/env python3
"""A small reimplementation of tex-fmt behavior for the benchmark."""
from __future__ import annotations

import os
import sys
import re
import fnmatch
from dataclasses import dataclass, field
from pathlib import Path

VERSION = "0.5.6"
DEFAULT_LISTS = ["itemize", "enumerate", "description", "inlineroman", "inventory"]
DEFAULT_VERBATIMS = ["verbatim", "Verbatim", "lstlisting", "minted", "comment"]
DEFAULT_NO_INDENT = ["document"]
DEFAULT_WRAP_CHARS = [" "]
FORMAT_EXTS = {".tex", ".bib", ".cls", ".sty"}


def auto_wrapmin(wraplen: int) -> int:
    return wraplen - 10 if wraplen >= 50 else wraplen


@dataclass
class Options:
    check: bool = False
    print_: bool = False
    fail_on_change: bool = False
    recursive: bool = False
    wrap: bool = True
    wraplen: int = 80
    wrapmin: int = 70
    tabsize: int = 2
    tabchar: str = "space"  # "space" or "tab"
    stdin: bool = False
    config: str | None = None
    verbosity: str = "warn"  # error, warn, info, trace
