    # meta and files
    opts.files = cli.files
    opts.help = cli.help; opts.version = cli.version; opts.args = cli.args
    opts.man = cli.man; opts.completion = cli.completion; opts.noconfig = cli.noconfig
    # verbosity precedence
    if cli.cli_quiet: opts.verbosity = "error"
    if cli.cli_verbose: opts.verbosity = "info"
    if cli.cli_trace: opts.verbosity = "trace"
    if opts.wrapmin > opts.wraplen:
        opts.wrapmin = opts.wraplen
    return opts


def normalize_filename_for_display(arg: str) -> str:
    # Append .tex when the file-name component has no extension.  Directories are
    # handled later, but for --args clap-like display also normalizes positionals.
    if arg.endswith(os.sep):
        return arg
    base = os.path.basename(arg)
    if base in ("", ".", ".."):
        return arg
    # pathlib treats '.foo' as suffix ''; tex-fmt does too for extensionless names.
    if Path(base).suffix == "":
        return arg + ".tex"
    return arg


def normalize_for_processing(arg_original: str) -> tuple[str, bool]:
    # returns (path, is_directory_arg)
    if os.path.isdir(arg_original):
        return arg_original, True
    return normalize_filename_for_display(arg_original), False


def level_value(verbosity: str) -> int:
    return {"error": 0, "warn": 1, "info": 2, "trace": 3}.get(verbosity, 1)


class Logger:
    def __init__(self, opts: Options, file_label: str):
        self.opts = opts
        self.file_label = file_label

    def log(self, lvl: str, msg: str) -> None:
        lv = {"ERROR": 0, "WARN": 1, "INFO": 2, "TRACE": 3}[lvl]
        if level_value(self.opts.verbosity) >= lv:
            eprint(f"{lvl}: tex-fmt {self.file_label}: {msg} ")

    def error(self, msg: str) -> None: self.log("ERROR", msg)
    def warn(self, msg: str) -> None: self.log("WARN", msg)
    def info(self, msg: str) -> None: self.log("INFO", msg)
    def trace(self, msg: str) -> None: self.log("TRACE", msg)


def first_comment_index(s: str) -> int | None:
    for i, ch in enumerate(s):
        if ch == "%" and (i == 0 or s[i-1] != "\\"):
            return i
    return None


def code_part(s: str) -> str:
    idx = first_comment_index(s)
    return s if idx is None else s[:idx]


def has_unescaped_comment(s: str) -> bool:
    return first_comment_index(s) is not None


def parse_env_at(s: str, i: int, kind: str) -> tuple[str | None, int]:
    prefix = "\\" + kind + "{"
    if not s.startswith(prefix, i):
        return None, i
    start = i + len(prefix)
    end = s.find("}", start)
    if end == -1:
        return None, i
    return s[start:end], end + 1


def is_item_at(s: str, i: int) -> bool:
    if not s.startswith("\\item", i):
        return False
    j = i + 5
    return j >= len(s) or not (s[j].isalpha())


def split_structural(raw_line: str) -> list[str]:
    """Split before \begin, \end, or \item occurring after other code."""
    segments: list[str] = []
    remaining = raw_line.rstrip(" \t")
    while True:
        cpart = code_part(remaining)
        split_at = None
        i = 0
        while i < len(cpart):
            found = False
            if cpart.startswith("\\begin{", i) or cpart.startswith("\\end{", i) or is_item_at(cpart, i):
                if remaining[:i].strip() != "":
                    split_at = i
                    break
                # command at beginning: skip it and continue looking for later commands
                found = True
            i += 1
        if split_at is None:
            segments.append(remaining)
            break
        before = remaining[:split_at].rstrip(" \t")
        after = remaining[split_at:].lstrip(" \t")
        if before != "" or not segments:
            segments.append(before)
        remaining = after
    return segments


def find_verbatim_begin(seg: str, verbatims: list[str]) -> str | None:
    cp = code_part(seg)
    for m in re.finditer(r"\\begin\{([^}]*)\}", cp):
        env = m.group(1)
        if env in verbatims:
            return env
    return None


def contains_verbatim_end(seg: str, env: str) -> bool:
    return f"\\end{{{env}}}" in code_part(seg)


def env_delta(env: str, begin: bool, opts: Options) -> int:
    if env in opts.no_indent_envs or env in opts.verbatims:
        return 0
    if env in opts.lists:
        return 2 if begin else -2
    return 1 if begin else -1


@dataclass
class DeltaResult:
    actual_delta: int = 0
    actual_min_prefix: int = 0
    visual_min_prefix: int = 0


def compute_deltas(content: str, opts: Options) -> DeltaResult:
    cp = code_part(content)
    actual = 0
    vis = 0
    min_actual = 0
    min_vis = 0
    i = 0
    while i < len(cp):
        env, new_i = parse_env_at(cp, i, "begin")
        if env is not None:
            d = env_delta(env, True, opts)
            actual += d; vis += d
            min_actual = min(min_actual, actual); min_vis = min(min_vis, vis)
            i = new_i
            continue
        env, new_i = parse_env_at(cp, i, "end")
        if env is not None:
            d = env_delta(env, False, opts)
            actual += d; vis += d
            min_actual = min(min_actual, actual); min_vis = min(min_vis, vis)
            i = new_i
            continue
        if is_item_at(cp, i):
            # \item visually belongs one level above its following text but does
            # not affect the actual indentation state.
            vis -= 1
            min_vis = min(min_vis, vis)
            i += 5
            continue
        ch = cp[i]
        if ch in "([{":
            actual += 1; vis += 1
            min_actual = min(min_actual, actual); min_vis = min(min_vis, vis)
        elif ch in ")]}":
            actual -= 1; vis -= 1
            min_actual = min(min_actual, actual); min_vis = min(min_vis, vis)
        i += 1
    return DeltaResult(actual, min_actual, min_vis)


class Formatter:
    def __init__(self, opts: Options, logger: Logger):
        self.opts = opts
        self.logger = logger
        self.current = 0
        self.output: list[str] = []
        self.out_line_no = 0
        self.leading_blank_count = 0
        self.last_zero_line = 1
        self.first_negative: int | None = None
        self.in_verbatim: str | None = None
        self.format_off = False

    def add_line(self, line: str) -> bool:
        # line is already without trailing whitespace
        if line == "":
            if not self.output or all(x == "" for x in self.output):
                if self.leading_blank_count < 2:
                    self.output.append(""); self.out_line_no += 1; self.leading_blank_count += 1
                    return True
                return False
            if self.output[-1] != "":
                self.output.append(""); self.out_line_no += 1
                return True
            return False
        self.output.append(line)
        self.out_line_no += 1
        return True

    def trim_trailing_blanks(self) -> None:
        while self.output and self.output[-1] == "":
            self.output.pop()

    def warn_negative_line(self, input_lineno: int, content: str) -> None:
        if self.first_negative is None:
            self.first_negative = self.out_line_no + 1
        self.logger.warn(f"Line {self.out_line_no + 1} ({input_lineno}). Indent is negative. {content}")

    def process_chunk(self, content: str, input_lineno: int) -> None:
        if content == "":
            self.add_line("")
            return
        before = self.current
        deltas = compute_deltas(content, self.opts)
        visual = before + min(0, deltas.visual_min_prefix)
        actual_min_abs = before + min(0, deltas.actual_min_prefix)
        actual_after = before + deltas.actual_delta
        # The original reports negative indentation for true delimiter/env
        # imbalance, not for a top-level \item pseudo-dedent.
        if before < 0 or actual_min_abs < 0 or actual_after < 0:
            self.warn_negative_line(input_lineno, content)
        if before == 0 and visual <= 0:
            self.last_zero_line = self.out_line_no + 1
        line = self.opts.indent(max(0, visual)) + content
        self.add_line(line)
        self.current = actual_after
        self.logger.trace(f"Line {self.out_line_no} ({input_lineno}). Indent: actual = {self.current}, visual = {max(0, visual)}: {content}")

    def estimate_visual_for_width(self, content: str) -> int:
        # Look only up to the target area so a far-away closing delimiter does
        # not dedent earlier wrapped chunks.
        window_len = max(self.opts.wrapmin, 1)
        prefix = content[:window_len]
        d = compute_deltas(prefix, self.opts)
        return self.current + min(0, d.visual_min_prefix)

    def break_points(self, text: str) -> list[tuple[int, int]]:
        # (cut_index, drop_count).  Space is removed; custom chars stay at EOL.
        pts: list[tuple[int, int]] = []
        chars = set(self.opts.wrap_chars)
        # Always support spaces.
        chars.add(" ")
        for i, ch in enumerate(text):
            if ch == " ":
                pts.append((i, 1))
            elif ch in chars:
                pts.append((i + 1, 0))
        # no zero-length chunks
        return [(c, d) for c, d in pts if c > 0]

    def choose_wrap(self, text: str, visual_level: int) -> tuple[str, str, bool]:
        """Return (chunk, remainder, bad_wrap_warning)."""
        if not self.opts.wrap or self.opts.wraplen <= 0:
            return text, "", self.opts.wrap and len(self.opts.indent(max(0, visual_level)) + text) > self.opts.wraplen
        prefix_len = len(self.opts.indent(max(0, visual_level)))
        if prefix_len + len(text) <= self.opts.wraplen:
            return text, "", False
        limit = self.opts.wraplen - prefix_len
        target = self.opts.wrapmin - prefix_len
        if target <= 0:
            target = limit
        if limit <= 0:
            return text, "", True
        pts = self.break_points(text)
        if not pts:
            return text, "", True
        before_target = [(c, d) for c, d in pts if c < target]
        warn = False
        if before_target:
            cut, drop = before_target[-1]
        else:
            before_limit = [(c, d) for c, d in pts if c <= limit]
            if before_limit:
                cut, drop = before_limit[-1]
                if cut >= limit:
                    warn = True
            else:
                after_limit = [(c, d) for c, d in pts if c > limit]
                if after_limit:
                    cut, drop = after_limit[0]
                    warn = True
                else:
                    return text, "", True
        chunk = text[:cut].rstrip(" \t")
        rest = text[cut + drop:].lstrip(" \t")
        if chunk == "":
            return text, "", True
        if prefix_len + len(chunk) > self.opts.wraplen:
            warn = True
        return chunk, rest, warn

    def process_wrappable(self, content: str, input_lineno: int) -> None:
        remaining = content
        comment_cont = False
        while remaining != "":
            visual_est = self.estimate_visual_for_width(remaining)
            chunk, rest, bad = self.choose_wrap(remaining, visual_est)
            if bad:
                self.logger.warn(f"Line {self.out_line_no + 1} ({input_lineno}). Line cannot be wrapped. {chunk}")
            self.process_chunk(chunk, input_lineno)
            if not rest:
                break
            if comment_cont or has_unescaped_comment(chunk):
                comment_cont = True
                rest = rest.lstrip(" \t")
                if not rest.startswith("%"):
                    rest = "% " + rest
            remaining = rest

    def process_normal_segment(self, seg: str, input_lineno: int) -> None:
        raw_trimmed = seg.rstrip(" \t")
        content = raw_trimmed.strip()
        if content == "":
            self.add_line("")
            return
        verb_env = find_verbatim_begin(raw_trimmed, self.opts.verbatims)
        if verb_env is not None:
            self.add_line(raw_trimmed)
            self.in_verbatim = verb_env
            if contains_verbatim_end(raw_trimmed, verb_env):
                self.in_verbatim = None
            return
        self.process_wrappable(content, input_lineno)

    def format(self, text: str) -> str:
        # Normalize line endings; output always uses LF and has one final LF.
        text = text.replace("\r\n", "\n").replace("\r", "\n")
        lines = text.split("\n")
        # If the input ended with a newline, split() creates a final empty line;
        # keep it through processing so blank-collapsing/trimming is uniform.
        for idx, raw in enumerate(lines, start=1):
            raw = raw.rstrip(" \t")
            if self.in_verbatim is not None:
                self.add_line(raw)
                if contains_verbatim_end(raw, self.in_verbatim):
                    self.in_verbatim = None
                continue
            if self.format_off:
                self.add_line(raw)
                if "% tex-fmt: on" in raw:
                    self.format_off = False
                continue
            if "% tex-fmt: skip" in raw:
                self.add_line(raw)
                continue
            if "% tex-fmt: off" in raw:
                self.add_line(raw)
                self.format_off = True
                continue
            for seg in split_structural(raw):
                self.process_normal_segment(seg, idx)
        self.trim_trailing_blanks()
        if self.current != 0:
            self.logger.warn(f"Indent does not return to zero. Last non-indented line is line {self.last_zero_line}")
        if self.first_negative is not None:
            self.logger.warn(f"Negative indents. First negatively indented line is line {self.first_negative}")
        if not self.output:
            return "\n"
        return "\n".join(self.output) + "\n"


def format_text(text: str, opts: Options, label: str, stdin_bytes: int | None = None) -> str:
    logger = Logger(opts, label)
    if stdin_bytes is not None:
        logger.trace(f"Read {stdin_bytes} bytes.")
    logger.info("Formatting started.")
    fmt = Formatter(opts, logger)
    out = fmt.format(text)
    logger.info("Formatting complete.")
    return out


def print_args(opts: Options) -> None:
    def row(label: str, value: str):
        print(f"  {label:<25}{value}")
    def multi(label: str, vals: list[str]):
        if vals:
            row(label, vals[0])
            for v in vals[1:]:
                print(" " * 27 + v)
        else:
            row(label, "")
    print("tex-fmt")
    row("check:", str(opts.check).lower())
    row("print:", str(opts.print_).lower())
    row("fail-on-change:", str(opts.fail_on_change).lower())
    row("wrap:", str(opts.wrap).lower())
    row("wraplen:", str(opts.wraplen))
    row("wrapmin:", str(opts.wrapmin))
    row("tabsize:", str(opts.tabsize))
    row("tabchar:", opts.tabchar)
    row("stdin:", str(opts.stdin).lower())
    row("config:", opts.config if opts.config is not None else "None")
    row("verbosity:", opts.verbosity)
    multi("lists:", opts.lists)
    multi("verbatims:", opts.verbatims)
    multi("no-indent-envs:", opts.no_indent_envs)
    multi("wrap-chars:", opts.wrap_chars)
    if opts.files:
        multi("files:", opts.files)


